// Brings the node_modules of main to a pull request instead of reinstalling them, for the
// node_modules restore benchmark: a job that starts from an image of main only reinstalls what the
// pull request changes. It runs with the Node.js of the checkout and imports its build scripts.
//
//   node mutate.ts state --root DIR
//     Compares the install state that build/npm/postinstall.ts saved in node_modules/.postinstall-state
//     (the hashes of the package.json, package-lock.json and .npmrc of every folder, of .nvmrc, and the
//     Node.js version) with the checkout, and prints the folders whose inputs changed.
//   node mutate.ts patch-postinstall --root DIR
//     Makes build/npm/postinstall.ts skip the folders whose inputs did not change when
//     VSCODE_INSTALL_CHANGED_DIRS_ONLY is set. Today, any change reinstalls every folder.
//   node mutate.ts verify --root DIR
//     Checks that the installed packages of every folder are those of its package-lock.json: the
//     hidden lockfile that npm writes after it installs (node_modules/.package-lock.json), and the
//     package.json of every installed package.
//   node mutate.ts manifest --root DIR --out FILE
//     Writes the version and the number of files of every installed package of every folder.
//   node mutate.ts compare --a FILE --b FILE [--title TEXT]
//     Prints the packages that differ between two manifests, also to the job summary.

import * as fs from 'fs';
import * as path from 'path';
import { pathToFileURL } from 'url';

type Args = Map<string, string[]>;

function parseArgs(argv: readonly string[]): Args {
	const args: Args = new Map();
	for (let i = 0; i < argv.length; i += 2) {
		if (!argv[i].startsWith('--') || i + 1 >= argv.length) {
			throw new Error(`Unexpected argument: ${argv[i]}`);
		}
		const key = argv[i].slice(2);
		args.set(key, [...(args.get(key) ?? []), argv[i + 1]]);
	}
	return args;
}

function arg(args: Args, name: string, fallback?: string): string {
	const value = args.get(name)?.[0] ?? fallback;
	if (value === undefined) {
		throw new Error(`Missing --${name}`);
	}
	return value;
}

function readJson<T>(file: string): T | undefined {
	try {
		return JSON.parse(fs.readFileSync(file, 'utf8')) as T;
	} catch {
		return undefined;
	}
}

async function importRepository<T>(root: string, file: string): Promise<T> {
	return await import(pathToFileURL(path.join(root, file)).href) as T;
}

async function loadDirs(root: string): Promise<string[]> {
	const { dirs } = await importRepository<{ dirs: string[] }>(root, 'build/npm/dirs.ts');
	return dirs;
}

//#region state

interface InstallState {
	readonly nodeVersion: string;
	readonly fileHashes: Record<string, string>;
}

interface InstallStateModule {
	computeState(): InstallState;
	readSavedState(): InstallState | undefined;
}

function folderLabel(file: string): string {
	const dir = path.dirname(file).split(path.sep).join('/');
	return dir === '.' ? '(root)' : dir;
}

async function state(args: Args): Promise<void> {
	const root = path.resolve(arg(args, 'root'));
	const { computeState, readSavedState } = await importRepository<InstallStateModule>(root, 'build/npm/installStateHash.ts');
	const saved = readSavedState();
	const current = computeState();
	if (!saved) {
		console.log('::notice title=Install state::No saved install state: every folder reinstalls');
		return;
	}
	const files = [...new Set([...Object.keys(saved.fileHashes), ...Object.keys(current.fileHashes)])];
	const changed = files.filter(file => saved.fileHashes[file] !== current.fileHashes[file]).sort();
	const folders = [...new Set(changed.map(folderLabel))];
	console.log(JSON.stringify({ savedNode: saved.nodeVersion, currentNode: current.nodeVersion, changed }, undefined, '\t'));
	const node = saved.nodeVersion === current.nodeVersion ? '' : `, and Node.js ${saved.nodeVersion} became ${current.nodeVersion}`;
	console.log(`::notice title=Install state::${changed.length} of ${files.length} input files changed${node}, in ${folders.length} folders: ${folders.join(', ') || 'none'}`);
}

//#endregion

//#region patch-postinstall

async function patchPostinstall(args: Args): Promise<void> {
	const file = path.join(path.resolve(arg(args, 'root')), 'build', 'npm', 'postinstall.ts');
	let source = fs.readFileSync(file, 'utf8');
	const eol = source.includes('\r\n') ? '\r\n' : '\n';
	const replace = (pattern: RegExp, replacement: (match: string, ...groups: string[]) => string) => {
		if (!pattern.test(source)) {
			throw new Error(`${file} does not match ${pattern}`);
		}
		source = source.replace(pattern, replacement);
	};
	replace(/import \{([^}]*)\} from '\.\/installStateHash\.ts';/, (match, names) =>
		names.includes('readSavedState') ? match : `import {${names.trimEnd()}, readSavedState } from './installStateHash.ts';`);
	// The hashes of the folder must equal those of the saved state, which the image of main carries
	replace(/^\tconst _state = computeState\(\);/m, match => [
		match,
		`\tconst _saved = process.env['VSCODE_INSTALL_CHANGED_DIRS_ONLY'] ? readSavedState() : undefined;`,
		`\tconst isDirUnchanged = (dir: string) => _saved !== undefined`,
		`\t\t&& _saved.nodeVersion === _state.nodeVersion`,
		`\t\t&& _saved.fileHashes['.nvmrc'] === _state.fileHashes['.nvmrc']`,
		`\t\t&& ['package.json', 'package-lock.json', '.npmrc'].every(name => {`,
		`\t\t\tconst key = path.relative(root, path.join(root, dir, name));`,
		`\t\t\treturn _saved.fileHashes[key] === _state.fileHashes[key];`,
		`\t\t});`,
	].join(eol));
	replace(/^\t\t\tcontinue; \/\/ already executed in root\r?\n\t\t\}/m, match => [
		match,
		`\t\tif (isDirUnchanged(dir)) {`,
		`\t\t\tlog(dir, 'Unchanged since the saved install state, skipping.');`,
		`\t\t\tcontinue;`,
		`\t\t}`,
	].join(eol));
	fs.writeFileSync(file, source);
	console.log(`Patched ${file}`);
}

//#endregion

//#region verify

interface LockEntry {
	readonly version?: string;
	readonly resolved?: string;
	readonly integrity?: string;
	readonly link?: boolean;
	readonly optional?: boolean;
	readonly devOptional?: boolean;
	readonly os?: readonly string[];
	readonly cpu?: readonly string[];
}

interface Lockfile {
	readonly packages?: Record<string, LockEntry>;
}

function isInstalledPath(key: string): boolean {
	return key.startsWith('node_modules/') || key.includes('/node_modules/');
}

// postinstall.ts deletes the prebuilt @parcel/watcher modules after npm installs them
const PARCEL_WATCHER_PREBUILD = /(?:^|\/)node_modules\/@parcel\/watcher-[^/]+$/;

async function verify(args: Args): Promise<void> {
	const root = path.resolve(arg(args, 'root'));
	const totals = { folders: 0, packages: 0, skippedOptional: 0, removedByPostinstall: 0, missing: 0, mismatched: 0, extra: 0, wrongOnDisk: 0 };
	const problems: string[] = [];
	for (const dir of await loadDirs(root)) {
		const base = path.join(root, dir);
		const label = dir || '(root)';
		const locked = readJson<Lockfile>(path.join(base, 'package-lock.json'))?.packages;
		if (!locked) {
			continue;
		}
		totals.folders++;
		const installed = readJson<Lockfile>(path.join(base, 'node_modules', '.package-lock.json'))?.packages ?? {};
		for (const [key, entry] of Object.entries(locked)) {
			if (!isInstalledPath(key)) {
				continue;
			}
			const actual = installed[key];
			if (!actual) {
				// npm skips the optional packages of other platforms, as `npm ci` does
				if (entry.optional || entry.devOptional || entry.os || entry.cpu) {
					totals.skippedOptional++;
				} else {
					totals.missing++;
					problems.push(`${label}: ${key}@${entry.version} is missing`);
				}
				continue;
			}
			totals.packages++;
			const same = !!actual.link === !!entry.link
				&& actual.version === entry.version
				&& (entry.resolved === undefined || actual.resolved === entry.resolved)
				&& (entry.integrity === undefined || actual.integrity === entry.integrity);
			if (!same) {
				totals.mismatched++;
				problems.push(`${label}: ${key} is ${actual.version} from ${actual.resolved}, the lockfile wants ${entry.version} from ${entry.resolved}`);
				continue;
			}
			if (!entry.link) {
				const onDisk = readJson<{ version?: string }>(path.join(base, key, 'package.json'))?.version;
				if (onDisk === undefined && PARCEL_WATCHER_PREBUILD.test(key) && !fs.existsSync(path.join(base, key))) {
					totals.removedByPostinstall++;
				} else if (onDisk !== entry.version) {
					totals.wrongOnDisk++;
					problems.push(`${label}: ${key}/package.json has ${onDisk}, the lockfile wants ${entry.version}`);
				}
			}
		}
		for (const key of Object.keys(installed)) {
			if (isInstalledPath(key) && !locked[key]) {
				totals.extra++;
				problems.push(`${label}: ${key} is installed but not in the lockfile`);
			}
		}
	}
	for (const problem of problems.slice(0, 60)) {
		console.log(problem);
	}
	const ok = totals.missing + totals.mismatched + totals.extra + totals.wrongOnDisk === 0;
	console.log(`::notice title=Verify::node_modules ${ok ? 'match' : 'DO NOT match'} the lockfiles: ${JSON.stringify(totals)}`);
	if (!ok) {
		process.exitCode = 1;
	}
}

//#endregion

//#region manifest and compare

interface PackageRecord {
	readonly version?: string;
	readonly files?: number;
	readonly link?: string;
}

async function manifest(args: Args): Promise<void> {
	const root = path.resolve(arg(args, 'root'));
	const packages: Record<string, PackageRecord> = {};
	const relative = (full: string) => path.relative(root, full).split(path.sep).join('/');
	// Counts the files of a package, and lists the packages of its own node_modules
	const countFiles = (dir: string, isPackageRoot: boolean): number => {
		let files = 0;
		for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
			const full = path.join(dir, entry.name);
			if (entry.isDirectory() && isPackageRoot && entry.name === 'node_modules') {
				addNodeModules(full);
			} else if (entry.isDirectory()) {
				files += countFiles(full, false);
			} else {
				files++;
			}
		}
		return files;
	};
	const addPackage = (full: string, entry: fs.Dirent) => {
		if (entry.isSymbolicLink()) {
			packages[relative(full)] = { link: fs.readlinkSync(full).split(path.sep).join('/') };
		} else if (entry.isDirectory()) {
			const version = readJson<{ version?: string }>(path.join(full, 'package.json'))?.version;
			packages[relative(full)] = { version, files: countFiles(full, true) };
		}
	};
	const addNodeModules = (nodeModules: string) => {
		for (const entry of fs.readdirSync(nodeModules, { withFileTypes: true })) {
			// .bin, .package-lock.json, .postinstall-state, ...
			if (entry.name.startsWith('.')) {
				continue;
			}
			const full = path.join(nodeModules, entry.name);
			if (entry.name.startsWith('@') && entry.isDirectory()) {
				for (const scoped of fs.readdirSync(full, { withFileTypes: true })) {
					addPackage(path.join(full, scoped.name), scoped);
				}
			} else {
				addPackage(full, entry);
			}
		}
	};
	// The folders of build/azure-pipelines/common/listNodeModules.ts
	const walk = (dir: string, isRoot: boolean) => {
		for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
			if (!entry.isDirectory() || (isRoot && (/^out/.test(entry.name) || ['src', '.git', '.build'].includes(entry.name)))) {
				continue;
			}
			const full = path.join(dir, entry.name);
			if (entry.name === 'node_modules') {
				addNodeModules(full);
			} else {
				walk(full, false);
			}
		}
	};
	const start = performance.now();
	walk(root, true);
	const out = arg(args, 'out');
	fs.mkdirSync(path.dirname(out), { recursive: true });
	fs.writeFileSync(out, JSON.stringify(packages));
	const files = Object.values(packages).reduce((sum, record) => sum + (record.files ?? 0), 0);
	console.log(`${Object.keys(packages).length} packages, ${files} files, in ${((performance.now() - start) / 1000).toFixed(1)} s`);
}

function describe(record: PackageRecord): string {
	return record.link !== undefined ? `link to ${record.link}` : `${record.version} (${record.files} files)`;
}

async function compare(args: Args): Promise<void> {
	const a = JSON.parse(fs.readFileSync(arg(args, 'a'), 'utf8')) as Record<string, PackageRecord>;
	const b = JSON.parse(fs.readFileSync(arg(args, 'b'), 'utf8')) as Record<string, PackageRecord>;
	const onlyA: string[] = [];
	const onlyB: string[] = [];
	const differ: string[] = [];
	for (const key of new Set([...Object.keys(a), ...Object.keys(b)])) {
		const x = a[key];
		const y = b[key];
		if (!y) {
			onlyA.push(`${key}: ${describe(x)}`);
		} else if (!x) {
			onlyB.push(`${key}: ${describe(y)}`);
		} else if (x.version !== y.version || x.files !== y.files || x.link !== y.link) {
			differ.push(`${key}: ${describe(x)}, then ${describe(y)}`);
		}
	}
	const lines = [
		`### ${arg(args, 'title', 'Packages')}`,
		'',
		`${Object.keys(a).length} and ${Object.keys(b).length} packages: ${onlyA.length} only in the first, ${onlyB.length} only in the second, ${differ.length} that differ`,
		'',
	];
	for (const [label, list] of [['Only in the first', onlyA], ['Only in the second', onlyB], ['Differ', differ]] as const) {
		if (list.length) {
			lines.push(`${label}:`, '', ...list.sort().slice(0, 40).map(item => `- ${item}`));
			if (list.length > 40) {
				lines.push(`- and ${list.length - 40} more`);
			}
			lines.push('');
		}
	}
	console.log(lines.join('\n'));
	const summary = process.env['GITHUB_STEP_SUMMARY'];
	if (summary) {
		fs.appendFileSync(summary, lines.join('\n') + '\n');
	}
}

//#endregion

const [command, ...rest] = process.argv.slice(2);
const commands: Record<string, (args: Args) => Promise<void>> = { state, 'patch-postinstall': patchPostinstall, verify, manifest, compare };
const main = commands[command];
if (!main) {
	console.error(`Usage: node mutate.ts ${Object.keys(commands).join('|')} ...`);
	process.exit(1);
}
main(parseArgs(rest)).catch(err => {
	console.error(err);
	process.exit(1);
});
